export function formatAccreditationDate(iso: string): string {
  return new Date(iso).toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
  });
}

export function labelAccreditationMethod(method: string): string {
  const map: Record<string, string> = {
    income: 'Income',
    net_worth: 'Net Worth',
    credential: 'Credential',
    third_party_letter: 'Third-Party Letter',
    insider: 'Insider / Executive',
    investment_threshold: 'Investment Threshold',
  };
  return map[method] ?? method;
}

export function accreditationStatusBadgeClass(status: string): string {
  switch (status) {
    case 'pending':
      return 'cedros-admin-badge--pending';
    case 'approved':
      return 'cedros-admin-badge--approved';
    case 'rejected':
      return 'cedros-admin-badge--rejected';
    case 'expired':
      return 'cedros-admin-badge--expired';
    default:
      return '';
  }
}
